# 10_simA.R: Simulation A (statistical recovery). Responses are generated from KNOWN MS-GDUM spread-by-position parameters (fractional logit, T = 60 trials per set) in three scenarios:
#   none (null: endpoint curves equal), moderate, strong spread-by-position interaction (focal predictor P; nuisance predictor N has no interaction in every scenario).
# 500 sites, predictors P, N ~ N(0,1) independent; 50 replicates per scenario; random 70/30 site-level split (sets drawn within training / test sites); orders 2, 3, 4, 5, 8; identical sets, bases (training-site bases for prediction), penalties.
# Truth uses the population I-spline basis (all-site predictor values; no response information). Coefficient recovery uses a second fit on the population basis (same training sets). Replicates are never selected on predictive gain.
# Usage (final/, ZG_LIB6 set): NCORES=9 Rscript revision_sim/10_simA.R
source("revision_sim/00_sim_common.R"); NC <- as.integer(Sys.getenv("NCORES", "9")); NREP <- as.integer(Sys.getenv("NREP", "50")); ORDERS <- c(2, 3, 4, 5, 8); N_SITES <- 500; M <- 3000L; TRIALS <- as.integer(Sys.getenv("TRIALS", "60")); SUF <- if (TRIALS == 60L) "" else paste0("_T", TRIALS)  # T = binomial trials per set (response noise); T = 60 is the primary setting, larger T is a low-noise sensitivity run
SCN <- list(none = list(L = c(1.2, .8, .5), U = c(1.2, .8, .5)), moderate = list(L = c(1.6, 1, .6), U = c(.8, .5, .3)), strong = list(L = c(2.4, 1.4, .8), U = c(.2, .1, .05)))
true_coef <- function(nm, sc) { b <- setNames(rep(0, length(nm)), nm); b["intercept"] <- -1; b[paste0("P_f", 1:3, "_L")] <- sc$L; b[paste0("P_f", 1:3, "_U")] <- sc$U; b[paste0("N_f", 1:3, "_L")] <- c(.9, .6, .4); b[paste0("N_f", 1:3, "_U")] <- c(.9, .6, .4); b["P"] <- .15; b["P_quadratic"] <- -.05; b["N"] <- -.10; b }
one <- function(job) { sn <- job$sn; rep <- job$rep; sc <- SCN[[sn]]; set.seed(20000 + 1000 * match(sn, names(SCN)) + rep); env <- data.frame(P = rnorm(N_SITES), N = rnorm(N_SITES)); perm <- sample(N_SITES); tr <- sort(perm[1:350]); te <- sort(perm[351:500]); R <- list(); S <- list(); CF <- list()
  for (k in ORDERS) { il_tr <- sample_sets(length(tr), k, M, seed = 100000L + 1000L * rep + k); il_te <- sample_sets(length(te), k, M, seed = 200000L + 1000L * rep + k); o_tr <- matrix(tr[il_tr], ncol = k); o_te <- matrix(te[il_te], ncol = k)
    dpop_tr <- mk_design(env, o_tr, "interaction"); dpop_te <- mk_design(env, o_te, "interaction", ref = dpop_tr); Xtr <- lay_fn(dpop_tr$int, FALSE)$X; b <- true_coef(colnames(Xtr), sc); p_tr <- plogis(drop(Xtr %*% b)); p_te <- plogis(drop(lay_fn(dpop_te$int, FALSE)$X %*% b))
    y_tr <- rbinom(M, TRIALS, p_tr) / TRIALS; y_te <- rbinom(M, TRIALS, p_te) / TRIALS; w_tr <- rep(TRIALS, M); w_te <- rep(TRIALS, M)
    # truth on the matched-profile grid (population basis)
    grid <- data.frame(m = 0 + 1 * GRID_STD$m, h = GRID_STD$h); syn <- surface_env(env, "P", grid, k); dsyn <- mk_design(syn$env, syn$idx, "interaction", ref = dpop_tr); eta_true <- drop(lay_fn(dsyn$int, FALSE)$X %*% b)
    eta_avg <- drop(lay_fn(dsyn$int, FALSE)$X %*% avg_endpoints(b)); ev <- evaluate_order(env, tr, te, k, il_tr, il_te, y_tr, y_te, w_tr, w_te, list(eta = eta_true, resp = plogis(eta_true), eta_avg = eta_avg), 0, 1, keep_surface = TRUE)
    rr <- ev$rows; rr$oracle_D2_test <- d2_heldout(y_te, p_te, w_te, y_tr, w_tr); rr$scenario <- sn; rr$replicate <- rep; R[[length(R) + 1]] <- rr; if (!is.null(ev$surf)) { s <- ev$surf; s$scenario <- sn; s$replicate <- rep; S[[length(S) + 1]] <- s }
    # coefficient recovery: fits on the population basis (training sets only)
    for (ci in seq_len(nrow(CONFIGS))) { cf <- CONFIGS[ci, ]; if (cf$kind != "interaction") next; pen <- PEN; pen[["interaction_shrink"]] <- cf$shrink; d <- mk_design(env, o_tr, "interaction"); f <- tryCatch(fit_model("interaction", d, y_tr, w_tr, pen), error = function(e) NULL); if (is.null(f)) next
      cl <- f$coef; dP <- cl[paste0("P_f", 1:3, "_U")] - cl[paste0("P_f", 1:3, "_L")]; dN <- cl[paste0("N_f", 1:3, "_U")] - cl[paste0("N_f", 1:3, "_L")]; tP <- b[paste0("P_f", 1:3, "_U")] - b[paste0("P_f", 1:3, "_L")]
      CF[[length(CF) + 1]] <- data.frame(scenario = sn, replicate = rep, order = k, config = cf$config, converged = isTRUE(f$converged), term = c(paste0("delta_P_f", 1:3), "delta_P_sum", paste0("delta_N_f", 1:3), "delta_N_sum", "P_L_sum", "P_U_sum", "intercept"), estimate = c(dP, sum(dP), dN, sum(dN), sum(cl[paste0("P_f", 1:3, "_L")]), sum(cl[paste0("P_f", 1:3, "_U")]), cl[["intercept"]]),
        truth = c(tP, sum(tP), rep(0, 4), sum(b[paste0("P_f", 1:3, "_L")]), sum(b[paste0("P_f", 1:3, "_U")]), -1)) } }
  list(r = do.call(rbind, R), s = do.call(rbind, S), c = do.call(rbind, CF)) }
jobs <- do.call(c, lapply(names(SCN), function(sn) lapply(seq_len(NREP), function(r) list(sn = sn, rep = r)))); t0 <- Sys.time(); RES <- mclapply(jobs, one, mc.cores = NC, mc.preschedule = FALSE); cat("elapsed", format(Sys.time() - t0), "bad", sum(!vapply(RES, is.list, TRUE)), "\n")
M_ <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$r)); S_ <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$s)); C_ <- bind_rows(lapply(RES, function(x) if (is.list(x)) x$c))
write.csv(M_, sprintf("revision_sim/tables/simA_metrics%s.csv", SUF), row.names = FALSE); write.csv(S_, sprintf("revision_sim/tables/simA_surfaces%s.csv", SUF), row.names = FALSE); write.csv(C_, sprintf("revision_sim/tables/simA_coefficients%s.csv", SUF), row.names = FALSE)
write.csv(data.frame(scenario = rep(names(SCN), each = 3), term = rep(paste0("P_f", 1:3), 3), beta_L = unlist(lapply(SCN, `[[`, "L")), beta_U = unlist(lapply(SCN, `[[`, "U"))), "revision_sim/tables/simA_true_parameters.csv", row.names = FALSE)
cat("rows", nrow(M_), nrow(S_), nrow(C_), "nonconverged", sum(!M_$converged), "\n")
